import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnumChip } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"

/**
 * `SubmissionAttemptsDrawer` — a presentational overlay drawer listing every
 * past graded attempt at one challenge requirement, client-paginated. A row is
 * the select action: tapping it both picks that attempt and closes the drawer.
 * Pagination is owned inside this block (the full attempt list in, sliced
 * 6-at-a-time), not a caller-controlled `currentPage`/`totalPages` pair.
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id — the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` → the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set — pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent → the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent → the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) — this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed — highlighted with a trailing check. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /** `true` → this list's own fetch is in flight; the drawer shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the drawer falls to its empty message. */
    isEmpty?: boolean
    /** Truthy → the drawer falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (§14d.1) — real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page — same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape — tone/icon/text, all derived from data. */
const scoreChipFor = (attempt: SubmissionAttemptRecord): { tone: "success" | "danger" | "default"; icon?: typeof CheckCircleIcon; text: string } => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/** Turns one attempt into a {@link SurfaceCardListItem}'s free-form `content` — mirrors real `src`'s row exactly: attempt line + verdict chip + time-ago on line 1, model byline on line 2. */
const attemptRowContent = (attempt: SubmissionAttemptRecord, isSelected: boolean) => {
    const chip = scoreChipFor(attempt)

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={`Attempt ${attempt.attemptNumber}`}
                size="sm"
                weight="medium"

            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} />,
    ]

    // justify="between" pushes the timeago to the far edge — the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH gap={3} align="center" principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={attemptLabelAndChip} />,
        ...(attempt.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt.processedTimeAgo}
                size="xs"
                color="muted"

            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                label={`Graded by ${attempt.gradedByModel}`}
            />
        ),
        ...(attempt.modelCategory != null ? [() => (
            <EnumChip
                value={attempt.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}

            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                gap={3}
                align="center"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={attemptLineContent}
            />
        ),
        ...(attempt.gradedByModel != null ? [() => (
            <StackH gap={3} align="center" at="sm" principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={bylineContent}  />
        )] : []),
    ]

    // highlight-exception: the selected row's tint is baked into the row's own
    // content wrapper (a plain, un-tightened `<div>`), since `SurfaceCardListItem`
    // no longer takes a raw `className` — same class real `src`'s
    // `SurfaceListCardItem` uses.
    return (
        <div className={isSelected ? "bg-accent-soft hover:bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isLoading = false,
    isEmpty = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens — same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = {
        title: EMPTY_TITLE,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const skeletonRows = Array.from({ length: SKELETON_ATTEMPT_COUNT }, () => () => (
        <div className="h-16 w-full rounded-2xl bg-default/40" />
    ))

    // `selected` (a trailing check) is only wired for the FIXED title/subtitle row
    // shape — this row uses free-form `content` instead (2 lines, richer than that
    // shape fits), so the highlight is baked into `attemptRowContent`'s own wrapper
    // div, same class real `src`'s `SurfaceListCardItem` uses.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, attempt.id === selectedAttemptId),
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}


            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (§4) — the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}

                />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={`${DRAWER_TITLE} · ${attempts.length}`}
            body={() => (
                <AsyncContent
                    isLoading={isLoading}
                    skeleton={() => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            explain="Skeleton attempt rows — not group-boundary, because these are peer loading placeholders."
                            items={skeletonRows}
                        />
                    )}
                    isEmpty={isEmpty}
                    emptyContent={emptyContent}
                    error={error}
                    errorContent={errorContent}
                    content={() => (
                        <StackV
                            gap={4}
                            principle="content-row"
                            explain="Attempt list over optional pager — not sibling-stack, because these are related content regions."
                            items={listAndPager}
                        />
                    )}
                />
            )}
        />
    )
}

export { SubmissionAttemptsDrawer }

"use client"

import React, { useEffect, useRef } from "react"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link Turnstile}. */
export interface TurnstileProps {
    /** Callback triggered when Turnstile successfully validates the visitor. */
    onVerify: (token: string) => void
    /** Callback triggered when Turnstile token expires. */
    onExpire?: () => void
    /** Callback triggered on network or verification error. */
    onError?: () => void
}

/** Render options passed to `turnstile.render()`. */
interface TurnstileRenderOptions {
    sitekey: string
    callback: (token: string) => void
    "expired-callback": () => void
    "error-callback": () => void
}

/** Minimal subset of the Cloudflare Turnstile global API used in this module. */
interface TurnstileApi {
    render: (container: HTMLElement, options: TurnstileRenderOptions) => string
    remove: (widgetId: string) => void
}

/** Window augmented with the optional Turnstile global. */
interface WindowWithTurnstile extends Window {
    turnstile?: TurnstileApi
}

/**
 * Renders the Cloudflare Turnstile captcha widget dynamically.
 * Automatically loads the Turnstile script if not already present.
 * No-ops (returns null) when captcha is disabled in public config.
 */
export const Turnstile = ({ onVerify, onExpire, onError}: TurnstileProps) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const widgetIdRef = useRef<string | null>(null)

    useEffect(() => {
        const { enabled, siteKey } = publicEnv().captcha
        if (!enabled) return

        let isMounted = true

        const renderWidget = () => {
            const turnstile = (window as WindowWithTurnstile).turnstile
            if (!isMounted || !containerRef.current || !turnstile) return

            try {
                if (widgetIdRef.current !== null) {
                    turnstile.remove(widgetIdRef.current)
                }

                widgetIdRef.current = turnstile.render(containerRef.current, {
                    sitekey: siteKey,
                    callback: (token: string) => {
                        if (isMounted) onVerify(token)
                    },
                    "expired-callback": () => {
                        if (isMounted && onExpire) onExpire()
                    },
                    "error-callback": () => {
                        if (isMounted && onError) onError()
                    },
                })
            } catch (err) {
                console.error("[Turnstile] Render error:", err)
            }
        }

        const scriptId = "cloudflare-turnstile-script"
        let script = document.getElementById(scriptId) as HTMLScriptElement | null

        if (!script) {
            script = document.createElement("script")
            script.id = scriptId
            script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit"
            script.async = true
            script.defer = true
            document.body.appendChild(script)
        }

        const turnstile = (window as WindowWithTurnstile).turnstile
        if (turnstile) {
            renderWidget()
        } else {
            const onLoad = () => {
                renderWidget()
            }
            script.addEventListener("load", onLoad)
            return () => {
                isMounted = false
                script?.removeEventListener("load", onLoad)
                const activeTurnstile = (window as WindowWithTurnstile).turnstile
                if (widgetIdRef.current !== null && activeTurnstile) {
                    activeTurnstile.remove(widgetIdRef.current)
                }
            }
        }

        return () => {
            isMounted = false
            const activeTurnstile = (window as WindowWithTurnstile).turnstile
            if (widgetIdRef.current !== null && activeTurnstile) {
                activeTurnstile.remove(widgetIdRef.current)
            }
        }
    }, [onVerify, onExpire, onError])

    const { enabled } = publicEnv().captcha
    if (!enabled) return null

    return <div ref={containerRef} className={"flex justify-center my-2 min-h-[74px]"} />
}
export default Turnstile

import React from "react"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { EntityResultRow } from "@/components/blocks/learn/EntityResultRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/** One kind-bucketed section of RAG hits, already resolved (label + count) by the connected `MindMapNodeDrawer`. */
export interface MindMapNodeDrawerGroup {
    /** Bucket key (`content` · `flashcard` · `challenge` · `milestone`) — also the `React` list key. */
    key: string
    /** `t("mindMap.drawer.group.<key>")`, already resolved. */
    label: string
    /** `t("mindMap.drawer.count", { count })`, already interpolated. */
    countLabel: string
    /** This bucket's hits, relevance-ordered (RAG best-match first). */
    items: ReadonlyArray<SearchCourseContentItem>
}

/** All display text, already localized by the connected `MindMapNodeDrawer`; a story passes i18n keys. */
export interface MindMapNodeDrawerLabels {
    aboutEyebrow: string
    /** Header title fallback, shown while no keyword is selected. */
    titleFallback: string
    eyebrow: string
    emptyTitle: string
    /** Already interpolated with the keyword. */
    emptyDescription: string
    loadError: string
    retry: string
}

/** Props for {@link _MindMapNodeDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export interface MindMapNodeDrawerProps {
    /** The clicked concept's keyword (header title + what `labels.emptyDescription` was interpolated with). */
    keyword: string | null
    /** The keyword's authored explainer (localized) — renders above the RAG results as context. */
    desc?: string | null
    /** Whether the drawer is open. */
    isOpen: boolean
    /** Fired when the drawer requests to close (backdrop / close button). */
    onClose: () => void
    /** RAG hits, already bucketed into kind sections (lessons / flashcards / challenges / capstone). */
    groups: ReadonlyArray<MindMapNodeDrawerGroup>
    /** First load, nothing in hand → the whole tree shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero hits (and no error) → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Fired when a hit is picked — the connected file resolves the jump href and closes the drawer. */
    onSelectItem: (item: SearchCourseContentItem) => void
    labels: MindMapNodeDrawerLabels
}

/** How many placeholder sections/rows the loading skeleton mirrors — matches the common 1–2 group shape. */
const SKELETON_SECTION_COUNT = 2
const SKELETON_ROW_COUNT = 2

/**
 * PRESENTATIONAL drawer — the mind-map keyword's related-surfaces view, driven by plain props (no
 * store/SWR/i18n) so it is fully story-able. Renders the relevance-ordered RAG hits already bucketed
 * into kind sections (lessons / flashcards / challenges / capstone), each a jump link. Branches in
 * priority order error → skeleton → empty → content (`AsyncContentError`/`AsyncContentEmpty` for the
 * message branches; the skeleton is a small inline mirror of the group/row shape, per
 * `authoring/loading-and-skeleton.md`). See `tiers/split.md` — the connected `index.tsx` owns the
 * fetch, the bucketing, and i18n.
 *
 * @param props - {@link MindMapNodeDrawerProps}
 * @see Story: .storybook/stories/drawers/MindMapNodeDrawer/MindMapNodeDrawer.stories
 */
export const _MindMapNodeDrawer = ({
    keyword,
    desc,
    isOpen,
    onClose,
    groups,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onSelectItem,
    labels,
}: MindMapNodeDrawerProps) => {
    const { isMobile } = useSmViewpoint()

    // authored explainer — "understand the concept right in the drawer" (teacher, 2026-07-18) before
    // RAG lists where to dig deeper below. Always known from the click, never part of the RAG fetch,
    // so it never shimmers.
    const header: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={1}
            items={[
                () => <Typography size="xs" color="muted" text={labels.aboutEyebrow} />,
                () => <Typography size="h4" weight="bold" text={keyword ?? labels.titleFallback} />,
                ...(desc ? [() => <Typography size="sm" color="muted" text={desc} />] : []),
            ]}
        />
    )

    // small inline mirror of the [group label + bordered row list] shape — one Skeleton.Typography
    // per text node, the same structural nodes (SurfaceListCard, SurfaceListCardItem) real content
    // renders through, so the box doesn't jump when the data lands.
    const skeletonSections: Array<ComponentTypeWithSkeleton> = Array.from(
        { length: SKELETON_SECTION_COUNT },
        () => () => (
            <StackV
                gap={2}
                items={[
                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                    () => (
                        <SurfaceListCard bordered>
                            {Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                                <SurfaceListCardItem key={index}>
                                    <StackV
                                        gap={2}
                                        items={[
                                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                        ]}
                                    />
                                </SurfaceListCardItem>
                            ))}
                        </SurfaceListCard>
                    ),
                ]}
            />
        ),
    )

    const body: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.loadError} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (isSkeleton) {
            return <StackV gap={4} items={skeletonSections} />
        }
        if (isEmpty) {
            return <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyDescription} />
        }
        return (
            <StackV
                gap={4}
                items={[
                    // section label over the related-content groups (each an interactive nav list)
                    () => <Typography size="sm" weight="semibold" text={labels.eyebrow} />,
                    ...groups.map((group) => () => (
                        <LabeledCard frameless subtleLabel label={group.label} labelEnd={group.countLabel}>
                            <SurfaceListCard bordered>
                                {group.items.map((item, index) => (
                                    <EntityResultRow
                                        key={`${item.kind}-${item.contentId ?? item.deckId ?? item.taskId ?? index}`}
                                        item={item}
                                        showSnippet
                                        onSelect={onSelectItem}
                                    />
                                ))}
                            </SurfaceListCard>
                        </LabeledCard>
                    )),
                ]}
            />
        )
    }

    return (
        <DrawerShell
            identity={{ tier: "overlay", component: "MindMapNodeDrawer" }}
            isOpen={isOpen}
            onOpenChange={(open) => {
                if (!open) {
                    onClose()
                }
            }}
            placement={isMobile ? "bottom" : "right"}
            header={header}
            body={body}
        />
    )
}

import React from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** All display text, already localized by the connected `MiniCartDrawer`; a story passes i18n keys. */
export interface MiniCartDrawerLabels {
    /** `"${cart.title} · ${cart.itemsCount}"`, already interpolated with `count`. */
    header: string
    emptyTitle: string
    emptyDescription: string
    browseCourses: string
    errorTitle: string
    retry: string
    /** `cart.comboActive`/`cart.comboStart`, already picked+interpolated for the current `bundlePercent`. */
    comboLabel: string
    /** `cart.bundleBonus`, already interpolated — only shown while `bundlePercent > 0`. */
    bundleBonusChip: string
    /** `cart.comboNextHint`/`cart.comboMaxHint`, already picked+interpolated for `nextTierPercent`. */
    comboHint: string
    total: string
    /** `cart.savings`, already interpolated — only shown while `savingsVnd > 0`. */
    savings: string
    /** `cart.installmentHint`, already interpolated — only shown while `cheapestMonthlyVnd` is set. */
    installmentHint: string
    checkout: string
    viewFullCart: string
}

/** Props for {@link _MiniCartDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export interface MiniCartDrawerProps {
    isOpen: boolean
    onOpenChange: (open: boolean) => void
    /** Slide-in edge. `true` on mobile → bottom sheet. */
    isMobile: boolean
    /** First load, nothing in hand → the cart-list zone shimmers in place (co-located). */
    isSkeleton?: boolean
    /** Settled with zero lines → the empty message replaces the list. */
    isEmpty?: boolean
    /** Truthy → the cart-list zone falls to the error message (beats loading + empty). */
    error?: unknown
    onRetry?: () => void
    onBrowseCourses?: () => void
    items?: Array<CartItemEntity>
    /** courseId → the real checkout-preview line, for per-line pricing. */
    previewByCourse?: Map<string, CoursesCheckoutPreviewLine>
    isMutating?: boolean
    onRemove: (courseId: string) => void
    /** Combo-meter fill (0..3). */
    itemCount?: number
    /** Whether the current bundle tier is above zero — gates the bonus chip. */
    bundlePercent?: number
    /** First load of the checkout preview, cart already settled → the footer summary shimmers. */
    isPreviewSkeleton?: boolean
    /** The real checkout preview — total/savings/installments. `undefined` while pending or on error. */
    preview?: { totalChargedVnd: number; totalListVnd: number; savingsVnd: number }
    /** `true` → the preview fetch settled with an error; falls back to `fallbackTotalVnd`. */
    previewError?: boolean
    /** Sum of entity display prices — shown only when the preview failed to load. */
    fallbackTotalVnd?: number
    /** Cheapest installment monthly amount, already formatted. `null` → no installment plans exist. */
    cheapestMonthlyLabel?: string | null
    onCheckout?: () => void
    onViewFullCart?: () => void
    labels: MiniCartDrawerLabels
}

/**
 * Mini-cart drawer — the presentational half of {@link _MiniCartDrawer}'s connected
 * `MiniCartDrawer` (`index.tsx`): the slide-out cart confirmation + combo meter,
 * right on desktop / bottom-sheet on mobile. Composed on `DrawerShell` (the shared
 * panel-scaffold composite): a bordered `SurfaceListCard` reusing {@link CartLine}
 * (the SAME row the `/cart` page uses), a bundle-discount `ProgressMeter`, and a
 * footer with the real charged total + saving, a primary "Checkout" and a text
 * link to the full cart page. `error`/`isEmpty` fall to the shared
 * `AsyncContentError` / `AsyncContentEmpty` composites; otherwise the tree renders
 * with `isSkeleton` threaded down so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` — the connected `index.tsx` owns
 * the fetch, the stores, and the i18n.
 *
 * @param props - {@link MiniCartDrawerProps}
 */
export const _MiniCartDrawer = ({
    isOpen,
    onOpenChange,
    isMobile,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBrowseCourses,
    items = [],
    previewByCourse,
    isMutating = false,
    onRemove,
    itemCount = 0,
    bundlePercent = 0,
    isPreviewSkeleton = false,
    preview,
    previewError = false,
    fallbackTotalVnd = 0,
    cheapestMonthlyLabel = null,
    onCheckout,
    onViewFullCart,
    labels,
}: MiniCartDrawerProps) => {
    const comboLabelRow = [
        () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={labels.comboLabel} />,
        ...(isSkeleton
            ? [() => <Chip isSkeleton tone="accent" />]
            : bundlePercent > 0
                ? [() => <Chip tone="accent" text={labels.bundleBonusChip} />]
                : []),
    ]
    const comboMeterItems = [
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                align="center"
                justify="between"
                items={comboLabelRow}
            />
        ),
        () => <ProgressMeter value={itemCount} max={3} isSkeleton={isSkeleton} />,
        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.comboHint} />,
    ]
    const comboMeterSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={3} items={comboMeterItems} />
    )

    // Line list — reuses the SAME `CartLine` as the `/cart` page. `bordered`: this
    // list is NESTED inside the drawer surface, where `shadow-surface` renders
    // invisible against the parent (dark mode) — nested cards need a border to
    // delineate (`card.md` §surface-in-surface). The `/cart` PAGE keeps it
    // un-bordered (top-level on `bg-background`, shadow shows). `CartLine` has no
    // co-located skeleton of its own, so the loading rows are mirrored by hand,
    // same shape (leading tile · two text lines · trailing action).
    const cartLineSkeletonItems = [
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]}
            />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]
    const cartListSection: ComponentTypeWithSkeleton = () => (
        <SurfaceListCard bordered>
            {isSkeleton
                ? Array.from({ length: 2 }).map((_row, index) => (
                    <StackH
                        key={index}
                        gap={1}
                        principle="card-padding"
                        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome."
                        padding={5}
                        body={() => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center"
                                items={cartLineSkeletonItems}
                            />
                        )}
                    />
                ))
                : items.map((item) => (
                    <CartLine
                        key={item.id}
                        item={item}
                        previewLine={previewByCourse?.get(item.courseId)}
                        onRemove={onRemove}
                        isMutating={isMutating}
                    />
                ))}
        </SurfaceListCard>
    )

    // Body — error → skeleton → empty → content (BLOCK-8): the empty and error
    // surfaces are the shared `AsyncContent*` composites dropped in as their own
    // states; otherwise the ONE tree renders, with `isSkeleton` threaded down so
    // the shimmer mirrors the loaded shape.
    const cartBody: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return <StackV gap={6} isSkeleton={isSkeleton} items={[comboMeterSection, cartListSection]} />
    }

    const previewSkeletonTotalRow = [
        () => <Skeleton className="h-5 w-20 rounded-lg" />,
        () => <Skeleton className="h-7 w-32 rounded-lg" />,
    ]
    const totalPriceRow = [
        () => <Typography size="base" weight="semibold" text={labels.total} />,
        ...(preview
            ? [() => (
                <PriceTagInline
                    discounted={preview.totalChargedVnd}
                    original={preview.totalListVnd}
                    currency="VND"
                />
            )]
            // preview failed to load — fall back to the plain list
            // total (no bundle discount known) so the total is never blank.
            : previewError
                ? [() => <PriceTagInline discounted={fallbackTotalVnd} currency="VND" />]
                : []),
    ]
    const totalSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={totalPriceRow}
            />
        ),
        ...(preview && preview.savingsVnd > 0
            ? [() => <Typography size="sm" color="success-soft" text={labels.savings} />]
            : []),
        ...(cheapestMonthlyLabel != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentHint} />]
            : []),
    ]
    const footerItems = [
        () => (
            isPreviewSkeleton ? (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    items={previewSkeletonTotalRow}
                />
            ) : (
                <StackV gap={2} items={totalSummaryItems} />
            )
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                isDisabled={isMutating}
                onPress={onCheckout}
                label={labels.checkout}
                classNames={["w-full"]}
            />
        ),
        () => (
            <Button
                variant="tertiary"
                onPress={onViewFullCart}
                label={labels.viewFullCart}
                classNames={["w-full"]}
            />
        ),
    ]
    const footerSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={footerItems} />
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={labels.header}
            dialogWidth="cart"
            footerVariant="stacked"
            isSkeleton={isSkeleton}
            body={cartBody}
            footer={items.length > 0 ? footerSection : undefined}
            identity={{ tier: "overlay", component: "MiniCartDrawer" }}
        />
    )
}

import React from "react"
import { ClockIcon, SparkleIcon } from "@phosphor-icons/react"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `_PersonalProjectTaskAttemptsDrawer` — the AI-review history for one personal-
 * project milestone task: every attempt the learner submitted, each with its score,
 * a line of grader feedback, and when it was processed. Composes `DrawerShell` +
 * `AsyncContent` + `SurfaceCardList` (free-form rows). One `AttemptRow` leaf with a
 * co-located skeleton mirror; a `null` score renders a neutral "Grading" chip. No
 * pagination or footer action.
 *
 * Presentational: `isOpen`/`onOpenChange`.
 */

/** One AI-graded attempt at a personal-project milestone task. */
export interface PersonalProjectTaskAttempt {
    /** Stable id — the row's React key. */
    id: string
    /** 1-based order the attempt was made in — the block turns this into "Attempt N". */
    attemptNumber: number
    /** Points earned on this attempt. `null` → not graded yet (AI review still running). */
    score: number | null
    /** A short line of grader feedback, plain text. `null` → the line drops (§2, not every attempt carries one). */
    shortFeedback: string | null
    /** When this attempt was processed, already localized by the caller (dayjs/locale is app-layer logic). */
    processedAtLabel: string
}

/** Props for {@link _PersonalProjectTaskAttemptsDrawer}. */
export interface PersonalProjectTaskAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /**
     * Which edge the panel slides in from. @default "right"
     *
     * Caller-decided (Rule 13): the real app derives this from a viewport hook
     * (narrow screens open a bottom sheet instead), which is app wiring — this
     * block only accepts the resolved value.
     */
    placement?: "right" | "bottom"
    /** The attempts for this task, in display order. */
    attempts: Array<PersonalProjectTaskAttempt>
    /** `true` → this drawer's own fetch is in flight; the list shows its skeleton mirror. */
    isLoading?: boolean
    /** Empty-state message. Defaults to a standard "no attempts yet" line. */
    emptyLabel?: string
    /** Truthy → the list falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

/** Fixed, block-owned title — this drawer's whole reason to exist is this one list. */
const DRAWER_TITLE = "AI grading history"

const EMPTY_LABEL_DEFAULT = "No submissions yet for this task."
const ERROR_TITLE = "Couldn't load the AI grading history"

/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ROW_COUNT = 3

/** Props for the local {@link AttemptRow} leaf. */
interface AttemptRowProps {
    /** The attempt's data. Omitted only in the skeleton branch. */
    attempt?: PersonalProjectTaskAttempt
    /** Resting state — the row keeps its shape, only the text shimmers. */
    isSkeleton?: boolean
}

/**
 * ONE attempt row: attempt-number label + sparkle/score chip on one line, an
 * optional feedback line, and a clock + processed-time line. The SAME shape
 * renders for real data and for the skeleton mirror (`isSkeleton` flips which
 * parts shimmer) — no second, hand-drawn placeholder tree (§6b).
 */
const AttemptRow = ({ attempt, isSkeleton = false }: AttemptRowProps) => {
    const scoreTone: ChipTone = attempt?.score != null ? "accent" : "default"
    const scoreLabel = attempt?.score != null ? `${attempt.score} points` : "Grading"
    // A missing attempt (real, §2) drops the line; the skeleton branch always
    // reserves it so the mirror's footprint matches a typical populated row.
    const showFeedback = isSkeleton || attempt?.shortFeedback != null

    const attemptLabelAndChip = [
        () => (
            <Typography
                size="sm"
                weight="medium"
                isSkeleton={isSkeleton}

                text={attempt != null ? `Attempt ${attempt.attemptNumber}` : undefined}
            />
        ),
        () => (
            <Chip
                icon={SparkleIcon}
                tone={scoreTone}
                isSkeleton={isSkeleton}
                text={scoreLabel}
            />
        ),
    ]

    const rowLines = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                justify="between"
                at="sm"
                isSkeleton={isSkeleton}
                items={attemptLabelAndChip}
            />
        ),
        ...(showFeedback ? [() => (
            <Typography
                size="sm"
                color="muted"
                isSkeleton={isSkeleton}

                text={attempt?.shortFeedback ?? undefined}
            />
        )] : []),
        () => (
            <InlineIconLabel
                icon={ClockIcon}
                tone="default"
                size="xs"
                isSkeleton={isSkeleton}
                label={attempt?.processedAtLabel ?? ""}
            />
        ),
    ]

    return (
        <StackV gap={2} isSkeleton={isSkeleton} items={rowLines} />
    )
}

/**
 * The AI-review attempts drawer. See the file header for why it is free-form
 * (not `SurfaceCardList`'s fixed row) and why it carries no pagination/footer.
 *
 * @param props - {@link PersonalProjectTaskAttemptsDrawerProps}
 */
const _PersonalProjectTaskAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    placement = "right",
    attempts,
    isLoading = false,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: PersonalProjectTaskAttemptsDrawerProps) => {
    const emptyContent: AsyncContentEmptyProps = {
        title: emptyLabel ?? EMPTY_LABEL_DEFAULT,
    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
        key: `skeleton-${index}`,
        content: () => <AttemptRow isSkeleton />,
    }))

    const items: Array<SurfaceCardListItem> = attempts.map((attempt) => ({
        key: attempt.id,
        content: () => <AttemptRow attempt={attempt} />,
    }))

    // A parent-forced skeleton and this drawer's own in-flight fetch share one flag.
    const loading = isLoading || isSkeleton

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={DRAWER_TITLE}
            identity={{ tier: "overlay", component: "PersonalProjectTaskAttemptsDrawer" }}
            body={() => (
                // One list owns all four states — error → skeleton → empty → content.
                // While loading it renders placeholder rows (the real items are still
                // empty) with the shimmer flowing down through `isSkeleton`; empty and
                // error are the shared `AsyncContent*` frames dropped in as its own slots.
                <SurfaceCardList
                    items={loading ? skeletonItems : items}
                    isSkeleton={loading}
                    error={error}
                    errorState={() => <AsyncContentError {...errorContent} />}
                    emptyState={() => <AsyncContentEmpty {...emptyContent} />}
                />
            )}
        />
    )
}

export { _PersonalProjectTaskAttemptsDrawer }

import React, { useEffect, useMemo, useState } from "react"
import { SparkleIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackH, StackV } from "@/components/frames/Stack"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/** Attempts per page inside the history drawer. */
const HISTORY_PAGE_SIZE = 6

/** Accessible name for the pager `<nav>` — `Pagination` already owns its own internal `aria-label`. */
const PAGER_ARIA_LABEL = "Task attempt history pagination"

/** One history row, already resolved by the connected `PersonalProjectTaskResultHistoryDrawer` — no raw entity. */
export interface PersonalProjectTaskResultHistoryRow {
    id: string
    /** Drives the verdict chip tone (comes straight off `attempt.passed`, no threshold math). */
    passed: boolean
    score: number | null
    servedModel: string | null
    category?: AiModelCategory
    /** `t("submissionAttempts.attemptLine", { number })`, already interpolated. */
    attemptLineLabel: string
    /** Relative time (`getTimeAgoLabel`), already localized — `null` when the attempt has no `processedAt`. */
    timeLabel: string | null
}

/** All display text, already localized by the connected `PersonalProjectTaskResultHistoryDrawer`; a story passes i18n keys. */
export interface PersonalProjectTaskResultHistoryDrawerLabels {
    /** Bare drawer title (`t("personalProjectResult.history")`) — the row count is appended alongside it. */
    historyLabel: string
    passed: string
    failed: string
    /** Empty-state title (no attempts yet). */
    emptyTitle: string
    /** Empty-state secondary line. Optional. */
    emptyDescription?: string
}

/** Props for {@link _PersonalProjectTaskResultHistoryDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export type PersonalProjectTaskResultHistoryDrawerProps = {
    /** Whether the drawer is open. */
    isOpen: boolean
    /** Open/close callback (also closes when a row is selected). */
    onOpenChange: (open: boolean) => void
    /** Full attempt list (newest first), already resolved to display rows. */
    rows: Array<PersonalProjectTaskResultHistoryRow>
    /** Currently selected attempt (highlighted row). */
    selectedAttemptId?: string
    /** Task max score (for the `x/max` label); 0 → show bare score. */
    maxScore: number
    /** Select an attempt (the page navigates `?attempt=`). */
    onSelect: (attemptId: string) => void
    labels: PersonalProjectTaskResultHistoryDrawerLabels
    /** AI-model tier → chip presentation, already localized — the model-byline recipe (`EnumChip`). */
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>
}

/** `x/max` when `maxScore` is set, otherwise the bare score. `null` reads as `0`. */
const scoreLabel = (score: number | null, maxScore: number) => (maxScore > 0 ? `${score ?? 0}/${maxScore}` : `${score ?? 0}`)

/**
 * One row's free-form content: attempt line + verdict chip + score on the first line
 * (score pushed to the far edge), an optional model byline (sparkle + model name +
 * tier chip) + time-ago on the second. Mirrors the sibling `SubmissionAttemptsDrawer`
 * row recipe — the model byline is composed here from `InlineIconLabel` + `EnumChip`
 * instead of the `ModelByline` block, since this tier may only import composites/frames.
 */
const attemptRowContent = (
    row: PersonalProjectTaskResultHistoryRow,
    isSelected: boolean,
    maxScore: number,
    labels: PersonalProjectTaskResultHistoryDrawerLabels,
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>,
) => {
    const servedModel = row.servedModel
    const category = row.category
    const timeLabel = row.timeLabel

    const attemptLabelAndChip = [
        () => <Typography size="sm" weight="medium" text={row.attemptLineLabel} />,
        () => <Chip tone={row.passed ? "success" : "danger"} text={row.passed ? labels.passed : labels.failed} />,
    ]

    const attemptLine = [
        () => <StackH gap={2} principle="chip-row" align="center" items={attemptLabelAndChip} explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."/>,
        () => (
            <Typography
                size="sm"
                color={row.passed ? "success-soft" : "muted"}
                text={scoreLabel(row.score, maxScore)}
            />
        ),
    ]

    const bylineParts = [
        ...(servedModel != null ? [() => (
            <InlineIconLabel icon={SparkleIcon} tone="default" size="xs" label={servedModel} />
        )] : []),
        ...(servedModel != null && category != null ? [() => (
            <EnumChip value={category} map={categoryMap} />
        )] : []),
    ]

    const rowContent = [
        () => <StackH gap={3} principle="sibling-stack" align="center" justify="between" items={attemptLine} explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."/>,
        ...(bylineParts.length > 0 || timeLabel != null ? [() => (
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="between"
                items={[
                    ...(bylineParts.length > 0 ? [() => <StackH gap={3} principle="sibling-stack" explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups." align="center" items={bylineParts} />] : []),
                    ...(timeLabel != null ? [() => <Typography size="xs" color="muted" text={timeLabel} />] : []),
                ]}
            />
        )] : []),
    ]

    // highlight-exception (mirrors `SubmissionAttemptsDrawer`): the selected row's tint is
    // baked into the row's own content wrapper — a plain, un-tightened `<div>` — since
    // `SurfaceCardListItem` no longer takes a raw `className` of its own.
    return (
        <div className={isSelected ? "bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * Personal-project task submission-history drawer — the presentational half of
 * {@link PersonalProjectTaskResultHistoryDrawer}: each attempt as a free-form
 * `SurfaceCardList` row (verdict, score, the AI model that graded it + tier, time),
 * paginated client-side. Right on desktop, bottom sheet on mobile. Sibling of
 * `SubmissionResultHistoryDrawer` (challenge) — here the verdict comes straight from
 * `row.passed` (no pass-threshold computation). See `tiers/split.md` — the connected
 * `index.tsx` owns i18n.
 *
 * @param props - {@link PersonalProjectTaskResultHistoryDrawerProps}
 */
export const _PersonalProjectTaskResultHistoryDrawer = ({
    isOpen,
    onOpenChange,
    rows,
    selectedAttemptId,
    maxScore,
    onSelect,
    labels,
    categoryMap,
}: PersonalProjectTaskResultHistoryDrawerProps) => {
    const { isMobile } = useSmViewpoint()
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(rows.length / HISTORY_PAGE_SIZE))
    const pagedRows = useMemo(
        () => rows.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [rows, page],
    )

    const items: Array<SurfaceCardListItem> = pagedRows.map((row) => ({
        key: row.id,
        content: () => attemptRowContent(row, row.id === selectedAttemptId, maxScore, labels, categoryMap),
        onPress: () => {
            onSelect(row.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}
                emptyState={() => <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyDescription} />}
            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` — the wrapping `<nav>`
            // is how this drawer's own accessible name still gets attached, same
            // convention `SubmissionAttemptsDrawer` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination currentPage={page} totalPages={totalPages} onPageChange={setPage} />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            identity={{ tier: "overlay", component: "PersonalProjectTaskResultHistoryDrawer" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={`${labels.historyLabel} · ${rows.length}`}
            body={() => <StackV gap={4} items={listAndPager} />}
        />
    )
}

import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import {
    AsyncContentEmpty,
    AsyncContentError,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { EnumChip } from "@/components/composites/chips/EnumChip"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@/components/blocks/learn/SubmissionScoreCard"
import { Pagination } from "@/components/atoms/navigation/Pagination"

/**
 * `_SubmissionAttemptsDrawer` — the full graded history of one challenge requirement:
 * every past attempt, client-paginated (6 per page), opened over the result screen.
 * Tapping any row both selects that attempt and closes the drawer. Composes
 * `DrawerShell` + `SurfaceCardList` (free-form rows), reusing the model-byline
 * recipe (`EnumChip`/`InlineIconLabel`/`MODEL_CATEGORY_MAP`).
 *
 * Loading is the co-located `isSkeleton` idiom (`loading-and-skeleton.md`): one row
 * function, `attemptRowContent`, renders BOTH the real row and the placeholder row —
 * `attempt` is only omitted for the placeholders, and every leaf shimmers through the
 * same flag. Error/empty are the shared `AsyncContentError`/`AsyncContentEmpty` frames,
 * dropped into `SurfaceCardList`'s own `errorState`/`emptyState` slots (`isEmpty` is
 * derived by that list from `items.length`, never passed in as a separate flag). The
 * selected row's highlight is `SurfaceCardListItem`'s own `tone="accent"` left-edge
 * band — no hand-rolled tint `<div>`.
 *
 * Ported from `.storybook/components/starci/overlays/drawers/SubmissionAttemptsDrawer/SubmissionAttemptsDrawer.tsx`
 * (renamed export only — see `index.tsx` for the connected wiring notes).
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id — the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` → the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set — pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent → the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent → the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link _SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) — this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed — highlighted with a left accent band. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /**
     * `true` → this list's own fetch is the FIRST load, nothing in hand yet — every
     * row mirrors itself as a shimmer instead of a hand-built placeholder tree.
     */
    isSkeleton?: boolean
    /** Truthy → the list falls to its error message (beats the skeleton, per `SurfaceCardList`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (§14d.1) — real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page — same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape — tone/icon/text, all derived from data. */
interface AttemptChipShape {
    tone: "success" | "danger" | "default"
    icon?: typeof CheckCircleIcon
    text?: string
}

const scoreChipFor = (attempt: SubmissionAttemptRecord): AttemptChipShape => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/**
 * Turns one attempt into the list row's free-form content — attempt line + verdict
 * chip + time-ago on line 1, model byline on line 2. `attempt` is omitted only for
 * the skeleton placeholder rows, which render this SAME tree with `isSkeleton` on
 * every leaf (§ `loading-and-skeleton.md`) instead of a second, hand-built shape.
 */
const attemptRowContent = (attempt: SubmissionAttemptRecord | undefined, isSkeleton: boolean) => {
    const chip: AttemptChipShape = attempt ? scoreChipFor(attempt) : { tone: "default" }

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={attempt != null ? `Attempt ${attempt.attemptNumber}` : undefined}
                size="sm"
                weight="medium"
                isSkeleton={isSkeleton}
                classNames={isSkeleton ? ["w-1/4"] : undefined}
            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} isSkeleton={isSkeleton} />,
    ]

    // justify="between" pushes the timeago to the far edge — the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH gap={3} principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            align="center" isSkeleton={isSkeleton} items={attemptLabelAndChip} />,
        ...(isSkeleton || attempt?.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt?.processedTimeAgo}
                size="xs"
                color="muted"
                isSkeleton={isSkeleton}
                classNames={isSkeleton ? ["w-1/4"] : undefined}
            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                isSkeleton={isSkeleton}
                label={attempt?.gradedByModel != null ? `Graded by ${attempt.gradedByModel}` : undefined}
            />
        ),
        ...(isSkeleton || attempt?.modelCategory != null ? [() => (
            <EnumChip
                value={attempt?.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}
                isSkeleton={isSkeleton}
            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="between"
                isSkeleton={isSkeleton}
                items={attemptLineContent}
            />
        ),
        ...(isSkeleton || attempt?.gradedByModel != null ? [() => (
            <StackH gap={3} principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                align="center" at="sm" isSkeleton={isSkeleton} items={bylineContent}  />
        )] : []),
    ]

    return <StackV gap={2} isSkeleton={isSkeleton} items={rowContent} />
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const _SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isSkeleton = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens — same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = { title: EMPTY_TITLE }
    const errorContent: AsyncContentErrorProps = { title: ERROR_TITLE, onRetry, retryLabel }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from({ length: SKELETON_ATTEMPT_COUNT }, (_, index) => ({
        key: `skeleton-${index}`,
        content: () => attemptRowContent(undefined, true),
    }))

    // `selected` reads as a left accent band (`SurfaceCardListItem.tone`) — the
    // existing DATA-signal vocabulary every card frame already shares — instead
    // of a hand-rolled tint wrapper around the row's own content.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, false),
        tone: attempt.id === selectedAttemptId ? "accent" : undefined,
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={isSkeleton ? skeletonItems : items}
                isSkeleton={isSkeleton}
                error={error}
                errorState={() => <AsyncContentError {...errorContent} />}
                emptyState={() => <AsyncContentEmpty {...emptyContent} />}
            />
        ),
        ...(!isSkeleton && totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (§4) — the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}
                />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            identity={{ tier: "overlay", component: "SubmissionAttemptsDrawer" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={`${DRAWER_TITLE} · ${attempts.length}`}
            body={() => <StackV gap={4} isSkeleton={isSkeleton} items={listAndPager} />}
        />
    )
}

export { _SubmissionAttemptsDrawer }

import React, { useEffect, useMemo, useState } from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackH, StackV } from "@/components/frames/Stack"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { ModelByline } from "@/components/blocks/grading/GradingByline"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/** Attempts per page inside the history drawer. */
const HISTORY_PAGE_SIZE = 6

/** One history row, already resolved by the connected `SubmissionResultHistoryDrawer` — no raw entity. */
export interface SubmissionResultHistoryRow {
    id: string
    attemptNumber: number
    score: number | null
    servedModel: string | null
    category?: AiModelCategory
    /** `t("submissionAttempts.attemptLine", { number })`, already interpolated. */
    attemptLineLabel: string
    /** Relative time (`getTimeAgoLabel`), already localized — `null` when the attempt has no `processedAt`. */
    timeLabel: string | null
}

/** All display text, already localized by the connected `SubmissionResultHistoryDrawer`; a story passes i18n keys. */
export interface SubmissionResultHistoryDrawerLabels {
    /** Bare drawer title (`t("submissionResult.history")`) — the row count is appended alongside it. */
    historyLabel: string
    passed: string
    failed: string
}

/** Props for {@link _SubmissionResultHistoryDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export type SubmissionResultHistoryDrawerProps = {
    /** Whether the drawer is open. */
    isOpen: boolean
    /** Open/close callback (also closes when a row is selected). */
    onOpenChange: (open: boolean) => void
    /** Full attempt list (newest first), already resolved to display rows. */
    rows: Array<SubmissionResultHistoryRow>
    /** Currently selected attempt (highlighted row). */
    selectedAttemptId?: string
    /** Requirement max score (for the `x/max` label + verdict threshold). */
    maxScore: number
    /** Pass threshold ratio (verdict per row). */
    passThreshold: number
    /** Select an attempt (the page navigates `?attempt=`). */
    onSelect: (attemptId: string) => void
    labels: SubmissionResultHistoryDrawerLabels
}

/**
 * One row's verdict + score text — guards an unknown threshold (treated as NOT passing).
 */
const isRowPassing = (score: number | null, maxScore: number, passThreshold: number) =>
    passThreshold > 0 && maxScore > 0 && (score ?? 0) >= passThreshold * maxScore

/** `x/max` when a max is known, the bare score otherwise. */
const rowScoreLabel = (score: number | null, maxScore: number) =>
    maxScore > 0 ? `${score ?? 0}/${maxScore}` : `${score ?? 0}`

/**
 * One history row's free-form content: attempt line + verdict chip on line one (score
 * pushed to the far edge via the track's own `justify="between"`), the grading-model
 * byline + relative time on line two. Reuses {@link ModelByline} — the SAME connected
 * block the graded-result card uses — instead of re-deriving the model/tier byline
 * locally, so the category label stays localized and in sync with every other reader
 * of it.
 */
const historyRowContent = (
    row: SubmissionResultHistoryRow,
    isPassing: boolean,
    scoreText: string,
    labels: SubmissionResultHistoryDrawerLabels,
) => {
    const timeLabel = row.timeLabel
    return (
        <StackV
            gap={2}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        align="center"
                        justify="between"
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    align="center"
                                    items={[
                                        () => <Typography size="sm" weight="medium" text={row.attemptLineLabel} />,
                                        () => <Chip tone={isPassing ? "success" : "danger"} text={isPassing ? labels.passed : labels.failed} />,
                                    ]}
                                />
                            ),
                            () => <Typography size="sm" color={isPassing ? "success-soft" : "muted"} text={scoreText} />,
                        ]}
                    />
                ),
                ...(row.servedModel != null || timeLabel != null ? [() => (
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        align="center"
                        at="sm"
                        justify="between"
                        items={[
                            () => <ModelByline model={row.servedModel} category={row.category} />,
                            ...(timeLabel != null ? [() => <Typography size="xs" color="muted" text={timeLabel} />] : []),
                        ]}
                    />
                )] : []),
            ]}
        />
    )
}

/**
 * Submission-history drawer — the presentational half of {@link SubmissionResultHistoryDrawer}: each
 * attempt as a free-form `SurfaceCardList` row (verdict, score, the AI model that graded it + tier,
 * time), paginated client-side. Right on desktop, bottom sheet on mobile. Composes `DrawerShell`
 * (the shared drawer scaffold) — the selected row's highlight is `SurfaceCardListItem`'s own
 * `tone="accent"` left-edge band, not a hand-rolled tint. See `tiers/split.md` — the connected
 * `index.tsx` owns i18n.
 *
 * @param props - {@link SubmissionResultHistoryDrawerProps}
 */
export const _SubmissionResultHistoryDrawer = ({
    isOpen,
    onOpenChange,
    rows,
    selectedAttemptId,
    maxScore,
    passThreshold,
    onSelect,
    labels,
}: SubmissionResultHistoryDrawerProps) => {
    const { isMobile } = useSmViewpoint()
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(rows.length / HISTORY_PAGE_SIZE))
    const pagedRows = useMemo(
        () => rows.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [rows, page],
    )

    // `tone="accent"` reads as a left accent band — the existing DATA-signal
    // vocabulary every card frame already shares — instead of a hand-rolled
    // tint wrapper around the row's own content.
    const items: Array<SurfaceCardListItem> = pagedRows.map((row) => ({
        key: row.id,
        content: () => historyRowContent(row, isRowPassing(row.score, maxScore, passThreshold), rowScoreLabel(row.score, maxScore), labels),
        tone: row.id === selectedAttemptId ? "accent" : undefined,
        onPress: () => {
            onSelect(row.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => <SurfaceCardList items={items} />,
        // `Pagination` hard-codes its own internal `aria-label` (atom, §4) — the
        // wrapping `<nav>` is how this drawer's own accessible name still gets
        // attached, same convention `SubmissionAttemptsDrawer` (drawersv2) uses.
        ...(totalPages > 1 ? [() => (
            <nav aria-label={labels.historyLabel}>
                <Pagination currentPage={page} totalPages={totalPages} onPageChange={setPage} />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={`${labels.historyLabel} · ${rows.length}`}
            body={() => <StackV gap={4} items={listAndPager} />}
            identity={{ tier: "overlay", component: "SubmissionResultHistoryDrawer" }}
        />
    )
}

import useSWR from "swr"
import { useAppSelector } from "@/redux/hooks"
import { AiQuotaTab } from "@/redux/slices/tabs"
import { queryMyCreditUsageHistory } from "@/modules/api/graphql/queries/query-my-credit-usage-history"
import { useAiQuotaOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Params for {@link useAiQuotaHistorySwr}. */
export interface UseAiQuotaHistorySwrParams {
    /** When true, fetch even if the modal is closed (e.g. `/profile/ai-usage`). */
    enabled?: boolean
}

/**
 * Credit-usage history for the AI quota modal History tab or full usage page.
 * @param params - Optional {@link UseAiQuotaHistorySwrParams}
 */
export const useAiQuotaHistorySwr = (
    params?: UseAiQuotaHistorySwrParams,
) => {
    const {
        isOpen,
    } = useAiQuotaOverlayState()
    const tab = useAppSelector((state) => state.tabs.aiQuotaTab)
    const shouldFetch = params?.enabled
        || (isOpen && tab === AiQuotaTab.History)

    return useSWR(
        shouldFetch
            ? ["QUERY_MY_CREDIT_USAGE_HISTORY_SWR"]
            : null,
        async () => {
            const response = await queryMyCreditUsageHistory({
                request: { limit: 100 },
            })
            const payload = response.data?.myCreditUsageHistory.data
            if (!payload) {
                throw new Error("Failed to fetch credit usage history")
            }
            return payload
        },
    )
}

import {
    useCallback,
} from "react"
import {
    useTranslations,
} from "next-intl"
import dayjs from "dayjs"

/**
 * Formats API reset timestamps for quota window copy (`aiQuota.windowResetAt`).
 * @returns Callback that maps an ISO-ish value to a localized reset line, or `null`.
 */
export const useWindowResetLabel = () => {
    const t = useTranslations()

    return useCallback(
        (value: string | null | undefined) => {
            if (!value) {
                return null
            }
            const time = dayjs(value).format("HH:mm DD/MM")
            return t("aiQuota.windowResetAt", { time })
        },
        [t],
    )
}

import dayjs from "dayjs"
import { AiCeilSurface } from "@/modules/api/graphql/mutations/types/set-ai-ceil"
import { AiSubTier } from "@/modules/api/graphql/queries/query-my-ai-settings"
import { AiQuotaTab as RealAiQuotaTab } from "@/redux/slices/tabs"
import type { QueryMyCreditUsageHistoryItem } from "@/modules/api/graphql/queries/types/my-credit-usage-history"
import type {
    AiQuotaHistoryChargeItem,
    AiQuotaHistoryChartPoint,
    AiQuotaHistorySurface,
} from "@/components/blocks/ai/AiQuotaHistoryPanel"
import type { AiQuotaModalTab, AiQuotaTier } from "./component"

/** How many trailing days the usage chart plots — mirrors the source's fixed 7-day window. */
const HISTORY_CHART_DAYS = 7

/**
 * `src`'s `AiSubTier | null` -> the blueprint's own `AiQuotaTier`. Same string
 * values, but the blueprint folds "no tier" into the union itself rather than a
 * separate nullable enum, so the connected file converts explicitly.
 *
 * @param raw - The real quota snapshot's tier, or null on the free lane.
 * @returns The matching blueprint {@link AiQuotaTier}.
 */
export const toAiQuotaTier = (raw: AiSubTier | null): AiQuotaTier => {
    switch (raw) {
    case AiSubTier.Plus:
        return "plus"
    case AiSubTier.Pro:
        return "pro"
    case AiSubTier.Max:
        return "max"
    default:
        return null
    }
}

/**
 * `src`'s `AiQuotaTab` (redux) -> the blueprint's own `AiQuotaModalTab`. Same
 * string values, but distinct TS declarations (enum vs string-literal union),
 * so the connected file converts explicitly rather than casting.
 *
 * @param raw - The redux-stored active tab.
 * @returns The matching blueprint {@link AiQuotaModalTab}.
 */
export const toAiQuotaModalTab = (raw: RealAiQuotaTab): AiQuotaModalTab => {
    switch (raw) {
    case RealAiQuotaTab.Subscription:
        return "subscription"
    case RealAiQuotaTab.History:
        return "history"
    case RealAiQuotaTab.Auto:
    default:
        return "auto"
    }
}

/**
 * The reverse of {@link toAiQuotaModalTab} — the blueprint's tab back to the
 * redux `AiQuotaTab` the `setAiQuotaTab` action expects.
 *
 * @param tab - The blueprint tab the viewer picked.
 * @returns The matching redux {@link RealAiQuotaTab}.
 */
export const toRealAiQuotaTab = (tab: AiQuotaModalTab): RealAiQuotaTab => {
    switch (tab) {
    case "subscription":
        return RealAiQuotaTab.Subscription
    case "history":
        return RealAiQuotaTab.History
    case "auto":
    default:
        return RealAiQuotaTab.Auto
    }
}

/**
 * `src`'s `AiCeilSurface | null` -> the blueprint's own `AiQuotaHistorySurface`.
 * A charge row predating the `surface` column (or from a surface not yet
 * passing it through) falls back to `"grade"`, mirroring the real
 * `HistoryTab`'s `purposeLabel` default.
 *
 * @param surface - The charge row's real surface, or null when unattributed.
 * @returns The matching blueprint {@link AiQuotaHistorySurface}.
 */
export const toAiQuotaHistorySurface = (surface: AiCeilSurface | null): AiQuotaHistorySurface => {
    switch (surface) {
    case AiCeilSurface.Interview:
        return "interview"
    case AiCeilSurface.Chatbot:
        return "chatbot"
    case AiCeilSurface.Grading:
    default:
        return "grade"
    }
}

/**
 * One real credit-usage-history row -> the blueprint's `AiQuotaHistoryChargeItem`.
 *
 * @param item - A row from `myCreditUsageHistory`.
 * @returns The matching blueprint {@link AiQuotaHistoryChargeItem}.
 */
export const toAiQuotaHistoryChargeItem = (item: QueryMyCreditUsageHistoryItem): AiQuotaHistoryChargeItem => ({
    key: item.id,
    model: item.model ?? undefined,
    surface: toAiQuotaHistorySurface(item.surface),
    occurredAt: item.createdAt,
    credits: item.credits,
})

/**
 * Buckets credit-usage-history rows into the trailing 7 day-buckets the usage
 * chart plots — ported from the real `HistoryTab`'s `chartData` memo.
 *
 * @param items - The history rows, or `undefined` before the first load lands.
 * @returns One {@link AiQuotaHistoryChartPoint} per day, oldest first.
 */
export const buildAiQuotaHistoryChartPoints = (
    items: Array<QueryMyCreditUsageHistoryItem> | undefined,
): Array<AiQuotaHistoryChartPoint> => {
    const today = dayjs().startOf("day")
    const buckets = new Map<string, number>()
    for (let offset = HISTORY_CHART_DAYS - 1; offset >= 0; offset--) {
        buckets.set(today.subtract(offset, "day").format("DD/MM"), 0)
    }
    for (const item of items ?? []) {
        const key = dayjs(item.createdAt).startOf("day").format("DD/MM")
        if (buckets.has(key)) {
            buckets.set(key, (buckets.get(key) ?? 0) + item.credits)
        }
    }
    return [...buckets.entries()].map(([day, credits]) => ({ day, credits }))
}

