import type React from "react"
import type { KeycloakIdentityProvider } from "@/modules/api/graphql/mutations/types/exchange-code-for-token"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * One OAuth shortcut button rendered above the credentials form.
 *
 * Mirrors a single identity-provider option (provider + icon + label key).
 */
export interface OauthButtonItem {
    /** OAuth identity provider sent to Keycloak. */
    provider: KeycloakIdentityProvider
    /** Icon component for the provider button. */
    icon: React.ComponentType<WithClassNames<undefined>>
    /** Translation key for the button label. */
    labelKey: string
}

"use client"

/**
 * **Sign-in step 2** — OTP entry after `signInInit` succeeds.
 *
 * Same singleton Formik as credentials step. Description uses `t.rich` so the email can be styled.
 * Submit runs the OTP verify branch in `useSignInForm` while `signInState === OTP`.
 *
 * @see {@link SignInSection} for step routing; mirror this folder when sign-up adds a verify-email step.
 */
import { InputOtp } from "@/components/atoms/forms"
import React from "react"
import { Modal } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useMutateSignInResendOtpSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignInResendOtpSwr"
import { useSignInForm } from "@/hooks/zustand/signIn/useSignInForm"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"

import { StackV, StackH } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link OtpState}. */
export interface OtpStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * OTPState component.
 */
export const OtpState = ({ hideCloseButton }: OtpStateProps = {}) => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const { trigger: mutateSignInResendOtp, isMutating: isResending } = useMutateSignInResendOtpSwr()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        isSubmitting,
    } = useSignInForm()

    const onResend = async () => {
        const challengeId = values.challengeId
        if (!challengeId) {
            return
        }
        await runGraphQL(
            async () => {
                const apolloResult = await mutateSignInResendOtp({
                    request: {
                        challengeId,
                    },
                })
                const env = apolloResult.data?.signInResendOtp
                if (!env?.success || !env.data?.challengeId) {
                    throw new Error(
                        env?.error ?? env?.message ?? "signInResendOtp failed"
                    )
                }
                await setFieldValue("challengeId", env.data.challengeId)
                await setFieldValue("otp", "", true)
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            }
        )
    }

    const otpInvalid = !!(touched.otp && errors.otp)

    const resendRow = [
        () => <Typography size="xs" color="muted" text={t("auth.signIn.otp.resend")} />,
        () => (
            <Typography
                size="xs"
                isLink
                color={isResending ? "muted" : "accent-soft"}
                onPress={() => {
                    if (isResending) return
                    void onResend()
                }}
                text={t("auth.signIn.otp.resendLink")}
            />
        ),
    ]

    const otpFieldItems = [
        () => (
            <InputOtp
                value={values.otp}
                onValueChange={(value) => setFieldValue("otp", value)}
                isInvalid={otpInvalid}
                errorMessage={otpInvalid ? errors.otp : undefined}
            />
        ),
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="center"
                items={resendRow}
            />
        ),
    ]

    const bodyItems = [
        () => (
            <Typography
                size="xs"
                color="muted"
                align="center"
                text={t.rich("auth.signIn.otp.desc", {
                    emailHighlight: (chunks) => (
                        <span className="text-accent-soft-foreground">{chunks}</span>
                    ),
                    email: values.email,
                })}
            />
        ),
        () => <StackV gap={4} items={otpFieldItems} />,
        () => (
            <Button
                variant="primary"
                classNames={["w-full"]}
                isPending={isSubmitting}
                label={t("auth.signIn.otp.submit")}
                onPress={() => submitForm()}
            />
        ),
    ]

    return (
        <>
            {!hideCloseButton && <Modal.CloseTrigger />}
            <Modal.Header>
                <Box className="pr-8">
                    <Typography weight="semibold" align="center" text={t("auth.signIn.otp.title")} />
                </Box>
            </Modal.Header>
            <Modal.Body>
                <StackV gap={6} items={bodyItems} />
            </Modal.Body>
        </>
    )
}

import { InputOtp } from "@/components/atoms/forms"
import React, { type ReactNode } from "react"
import { Modal } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"

import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"
import { Form } from "@/components/composites/form/Form"

/** Already-translated strings {@link _OtpState} renders — resolved by the connected `OtpState`, never `t()`/`t.rich()` itself. */
export interface OtpStateLabels {
    title: string
    /** `t.rich(...)`-resolved description with the email highlighted — already a built node. */
    desc: ReactNode
    resend: string
    resendLink: string
    submit: string
}

/** Props for {@link _OtpState}. */
export interface OtpStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
    /** Current 6-digit code value. */
    otp: string
    error?: string
    touched?: boolean
    /** True once the code passes format validation — gates the submit button. */
    isValid: boolean
    /** True while `signUpVerifyOtp` is in flight. */
    isSubmitting: boolean
    /** True while `signUpResendOtp` is in flight — locks the resend link. */
    isResending: boolean
    /** Already-translated strings — see {@link OtpStateLabels}. */
    labels: OtpStateLabels
    onChangeOtp: (value: string) => void
    /** Submit the form (the connected half runs `signUpVerifyOtp`). */
    onSubmit: () => void
    /** Request a fresh code (the connected half runs `signUpResendOtp`). */
    onResend: () => void
}

/**
 * Presentational OTP form — the second sign-up step, after `signUpInit`.
 * Renders its OWN `Modal.CloseTrigger` / `Modal.Header` / `Modal.Body` chrome
 * (not `ModalShell`): this section is also mounted bare on `/login`, where
 * there is no surrounding `<Modal>` at all — see {@link OtpState}.
 *
 * @param props - {@link OtpStateProps}
 */
export const _OtpState = ({
    hideCloseButton,
    otp,
    error,
    touched,
    isValid,
    isSubmitting,
    isResending,
    labels,
    onChangeOtp,
    onSubmit,
    onResend,
}: OtpStateProps) => {
    const showError = Boolean(touched && error)

    const resendRow = [
        () => <Typography size="xs" color="muted" text={labels.resend} />,
        () => (
            <Typography
                size="xs"
                color={isResending ? "muted" : "accent-soft"}
                isButton
                onPress={() => {
                    if (!isResending) onResend()
                }}
                text={labels.resendLink}
            />
        ),
    ]

    const otpFieldItems = [
        () => (
            <InputOtp
                length={6}
                value={otp}
                onValueChange={onChangeOtp}
                isInvalid={showError}
                errorMessage={showError ? error : undefined}
            />
        ),
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="center"
                items={resendRow}
            />
        ),
    ]

    const formBodyItems = [
        () => <Typography size="xs" color="muted" align="center" text={labels.desc} />,
        () => <StackV gap={3} items={otpFieldItems} />,
    ]

    return (
        <>
            {!hideCloseButton && <Modal.CloseTrigger />}
            <Modal.Header>
                <Box className="pr-8">
                    <Typography weight="semibold" align="center" text={labels.title} />
                </Box>
            </Modal.Header>
            <Modal.Body>
                <Form
                    onSubmit={onSubmit}
                    gap={6}
                    body={() => <StackV gap={6} items={formBodyItems} />}
                    actions={() => (
                        <Button
                            variant="primary"
                            classNames={["w-full"]}
                            isDisabled={!isValid}
                            isPending={isSubmitting}
                            label={labels.submit}
                            onPress={onSubmit}
                        />
                    )}
                />
            </Modal.Body>
        </>
    )
}

"use client"

/**
 * **Sign-up step 2** — OTP after `signUpInit`; resend uses {@link useMutateSignUpResendOtpSwr}.
 *
 * Submit runs `signUpVerifyOtp` via {@link useSignUpForm} while `signUpState === Otp`.
 * Container: owns the sign-up formik singleton, the resend mutation, and i18n;
 * hands resolved props to the presentational {@link _OtpState}. See `tiers/split.md`.
 */
import React, { useCallback } from "react"
import { useTranslations } from "next-intl"
import { Typography } from "@/components/atoms/text/Typography"
import { _OtpState } from "./component"
import { useMutateSignUpResendOtpSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignUpResendOtpSwr"
import { useSignUpForm } from "@/hooks/zustand/signUp/useSignUpForm"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link OtpState}. */
export interface OtpStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * OTP entry for completing GraphQL sign-up (mirrors sign-in `OtpState`).
 */
export const OtpState = ({ hideCloseButton }: OtpStateProps = {}) => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const { trigger: mutateSignUpResendOtp, isMutating: isResending } = useMutateSignUpResendOtpSwr()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        setFieldTouched,
        isSubmitting,
        isValid,
    } = useSignUpForm()

    const onResend = useCallback(
        async () => {
            const challengeId = values.challengeId
            if (!challengeId) {
                return
            }
            await runGraphQL(
                async () => {
                    const apolloResult = await mutateSignUpResendOtp({
                        request: {
                            challengeId,
                        },
                    })
                    const env = apolloResult.data?.signUpResendOtp
                    if (!env?.success || !env.data?.challengeId) {
                        throw new Error(
                            env?.error ?? env?.message ?? "signUpResendOtp failed"
                        )
                    }
                    await setFieldValue("challengeId", env.data.challengeId)
                    await setFieldValue("otp", "", true)
                    return env
                },
                {
                    showErrorToast: true,
                    showSuccessToast: true,
                }
            )
        },
        [
            values.challengeId,
            runGraphQL,
            mutateSignUpResendOtp,
            setFieldValue,
        ],
    )

    // `InputOtp` carries no `onBlur` — mark touched on the first edit instead
    // (same combined value+touch shape used across the sign-up fields).
    const onChangeOtp = useCallback(
        (value: string) => {
            setFieldValue("otp", value)
            setFieldTouched("otp", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onSubmit = useCallback(
        () => {
            submitForm()
        },
        [
            submitForm,
        ],
    )

    return (
        <_OtpState
            hideCloseButton={hideCloseButton}
            otp={values.otp}
            error={errors.otp}
            touched={touched.otp}
            isValid={isValid}
            isSubmitting={isSubmitting}
            isResending={isResending}
            onChangeOtp={onChangeOtp}
            onSubmit={onSubmit}
            onResend={onResend}
            labels={{
                title: t("auth.signUp.otp.title"),
                desc: t.rich("auth.signUp.otp.desc", {
                    emailHighlight: (chunks) => (
                        <Typography isInline size="xs" color="accent-soft" text={chunks} />
                    ),
                    email: values.email,
                }),
                resend: t("auth.signUp.otp.resend"),
                resendLink: t("auth.signUp.otp.resendLink"),
                submit: t("auth.signUp.otp.submit"),
            }}
        />
    )
}

