import React from "react"
import { Modal } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { Form } from "@/components/composites/form/Form"
import { EmailField } from "./EmailField"
import { PasswordField } from "./PasswordField"
import { AgreeToTermsRow } from "./AgreeToTermsRow"
import { SignInPrompt } from "./SignInPrompt"
import { Turnstile } from "@/components/blocks/auth/Turnstile"

/** Editable values {@link _RegistrationState} renders. */
export interface RegistrationStateValues {
    email: string
    password: string
    confirmPassword: string
    agreeToTerms: boolean
}

/** Field-level validation errors, keyed the same as {@link RegistrationStateValues}. */
export interface RegistrationStateErrors {
    email?: string
    password?: string
    confirmPassword?: string
    agreeToTerms?: string
}

/** Which fields have been interacted with — gates when an error is shown. */
export interface RegistrationStateTouched {
    email?: boolean
    password?: boolean
    confirmPassword?: boolean
    agreeToTerms?: boolean
}

/** Already-translated strings {@link _RegistrationState} renders — resolved by the connected `RegistrationState`, never `t()` itself. */
export interface RegistrationStateLabels {
    title: string
    desc: string
    submit: string
}

/** Props for {@link _RegistrationState}. */
export interface RegistrationStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
    values: RegistrationStateValues
    errors: RegistrationStateErrors
    touched: RegistrationStateTouched
    /** True while `signUpInit` is in flight — locks the submit button. */
    isSubmitting: boolean
    /** True when the form cannot be submitted yet (invalid, or captcha required but not solved). */
    isSubmitDisabled: boolean
    /** Whether the Cloudflare Turnstile widget should render at all. */
    captchaEnabled: boolean
    /** Already-translated strings — see {@link RegistrationStateLabels}. */
    labels: RegistrationStateLabels
    onChangeEmail: (value: string) => void
    onChangePassword: (value: string) => void
    onChangeConfirmPassword: (value: string) => void
    onChangeAgreeToTerms: (selected: boolean) => void
    /** Submit the form (the connected half runs `signUpInit`). */
    onSubmit: () => void
    /** Switch back to the sign-in tab. */
    onSwitchToSignIn: () => void
    onCaptchaVerify: (token: string) => void
    onCaptchaExpire: () => void
    onCaptchaError: () => void
}

/**
 * Presentational registration form — the first sign-up step (email, passwords,
 * terms). Renders its OWN `Modal.CloseTrigger` / `Modal.Header` / `Modal.Body`
 * chrome (not `ModalShell`): this section is also mounted bare on `/login`,
 * where there is no surrounding `<Modal>` at all — see {@link RegistrationState}.
 *
 * @param props - {@link RegistrationStateProps}
 */
export const _RegistrationState = ({
    hideCloseButton,
    values,
    errors,
    touched,
    isSubmitting,
    isSubmitDisabled,
    captchaEnabled,
    labels,
    onChangeEmail,
    onChangePassword,
    onChangeConfirmPassword,
    onChangeAgreeToTerms,
    onSubmit,
    onSwitchToSignIn,
    onCaptchaVerify,
    onCaptchaExpire,
    onCaptchaError,
}: RegistrationStateProps) => (
    <>
        {!hideCloseButton && <Modal.CloseTrigger />}
        <Modal.Header>
            <StackV
                gap={2}
                principle="title-subtitle"
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                items={[
                    () => (
                        <Box className="pr-8">
                            <Typography weight="semibold" align="center" text={labels.title} />
                        </Box>
                    ),
                    () => <Typography size="xs" color="muted" align="center" text={labels.desc} />,
                ]}
            />
        </Modal.Header>
        <Modal.Body>
            <Form
                onSubmit={onSubmit}
                gap={6}
                body={() => (
                    <StackV
                        gap={6}
                        items={[
                            () => (
                                <StackV
                                    gap={3}
                                    items={[
                                        () => (
                                            <EmailField
                                                value={values.email}
                                                error={errors.email}
                                                touched={touched.email}
                                                onChangeValue={onChangeEmail}
                                            />
                                        ),
                                        () => (
                                            <PasswordField
                                                kind="password"
                                                value={values.password}
                                                error={errors.password}
                                                touched={touched.password}
                                                onChangeValue={onChangePassword}
                                            />
                                        ),
                                        () => (
                                            <PasswordField
                                                kind="confirmPassword"
                                                value={values.confirmPassword}
                                                error={errors.confirmPassword}
                                                touched={touched.confirmPassword}
                                                onChangeValue={onChangeConfirmPassword}
                                            />
                                        ),
                                        () => (
                                            <AgreeToTermsRow
                                                isSelected={values.agreeToTerms}
                                                error={errors.agreeToTerms}
                                                touched={touched.agreeToTerms}
                                                onChangeSelected={onChangeAgreeToTerms}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                            ...(captchaEnabled
                                ? [() => (
                                    <Turnstile
                                        onVerify={onCaptchaVerify}
                                        onExpire={onCaptchaExpire}
                                        onError={onCaptchaError}
                                    />
                                )]
                                : []),
                        ]}
                    />
                )}
                actions={() => (
                    <StackV
                        gap={6}
                        items={[
                            () => (
                                <Button
                                    variant="primary"
                                    classNames={["w-full"]}
                                    isDisabled={isSubmitDisabled}
                                    isPending={isSubmitting}
                                    label={labels.submit}
                                    onPress={onSubmit}
                                />
                            ),
                            () => <SignInPrompt onSwitchToSignIn={onSwitchToSignIn} />,
                        ]}
                    />
                )}
            />
        </Modal.Body>
    </>
)

"use client"

/**
 * Sign-up step: registration form (email, passwords, terms).
 *
 * Container: owns the sign-up formik (singleton `useSignUpForm()`) and the
 * switch-to-sign-in action; resolves i18n; hands resolved props to the
 * presentational {@link _RegistrationState}. See `tiers/split.md`.
 */
import React, {
    useCallback,
} from "react"
import { useTranslations } from "next-intl"
import { _RegistrationState } from "./component"
import { useAppDispatch } from "@/redux/hooks"
import { AuthenticationModalTab, setAuthenticationModalTab } from "@/redux/slices/tabs"
import { resetSignUpState } from "@/redux/slices/state"
import { useSignUpForm } from "@/hooks/zustand/signUp/useSignUpForm"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link RegistrationState}. */
export interface RegistrationStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * Registration form container for the sign-up tab.
 */
export const RegistrationState = ({ hideCloseButton }: RegistrationStateProps = {}) => {
    const dispatch = useAppDispatch()
    const t = useTranslations()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        setFieldTouched,
        isSubmitting,
        resetForm,
        isValid,
    } = useSignUpForm()

    // `Input.*` atoms carry no `onBlur` — the field is marked touched on its
    // first edit instead (same combined value+touch shape already used for
    // `agreeToTerms` below), so the inline error still gates on interaction.
    const onChangeEmail = useCallback(
        (value: string) => {
            setFieldValue("email", value)
            setFieldTouched("email", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangePassword = useCallback(
        (value: string) => {
            setFieldValue("password", value)
            setFieldTouched("password", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangeConfirmPassword = useCallback(
        (value: string) => {
            setFieldValue("confirmPassword", value)
            setFieldTouched("confirmPassword", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangeAgreeToTerms = useCallback(
        (selected: boolean) => {
            // third arg true: run validation so `errors.agreeToTerms` clears when checked
            setFieldValue("agreeToTerms", selected, true)
            setFieldTouched("agreeToTerms", true, false)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onSubmit = useCallback(
        () => {
            submitForm()
        },
        [
            submitForm,
        ],
    )

    /** Reset the form + sign-up state, then switch to the sign-in tab. */
    const onSwitchToSignIn = useCallback(
        () => {
            resetForm()
            dispatch(resetSignUpState())
            dispatch(setAuthenticationModalTab(AuthenticationModalTab.SignIn))
        },
        [
            resetForm,
            dispatch,
        ],
    )

    const onCaptchaVerify = useCallback(
        (token: string) => {
            setFieldValue("captchaToken", token)
        },
        [
            setFieldValue,
        ],
    )
    const onCaptchaExpire = useCallback(
        () => {
            setFieldValue("captchaToken", undefined)
        },
        [
            setFieldValue,
        ],
    )
    const onCaptchaError = useCallback(
        () => {
            setFieldValue("captchaToken", undefined)
        },
        [
            setFieldValue,
        ],
    )

    const captchaEnabled = publicEnv().captcha.enabled
    const isSubmitDisabled = !isValid || (captchaEnabled && !values.captchaToken)

    return (
        <_RegistrationState
            hideCloseButton={hideCloseButton}
            values={values}
            errors={errors}
            touched={touched}
            isSubmitting={isSubmitting}
            isSubmitDisabled={isSubmitDisabled}
            captchaEnabled={captchaEnabled}
            labels={{
                title: t("auth.signUp.title"),
                desc: t("auth.signUp.desc"),
                submit: t("auth.signUp.submit"),
            }}
            onChangeEmail={onChangeEmail}
            onChangePassword={onChangePassword}
            onChangeConfirmPassword={onChangeConfirmPassword}
            onChangeAgreeToTerms={onChangeAgreeToTerms}
            onSubmit={onSubmit}
            onSwitchToSignIn={onSwitchToSignIn}
            onCaptchaVerify={onCaptchaVerify}
            onCaptchaExpire={onCaptchaExpire}
            onCaptchaError={onCaptchaError}
        />
    )
}

"use client"

/**
 * Sign-up section inside {@link AuthenticationModal}.
 *
 * Mirrors {@link SignInSection}: router on Redux `state.signUpState`.
 * Flow: **Registration** (`signUpInit`) → **Otp** (`signUpVerifyOtp`).
 *
 * ### Data layer
 * - {@link useMutateSignUpSwr} — GraphQL `signUpInit` (SWR singleton).
 * - {@link useMutateSignUpVerifyOtpSwr} — GraphQL `signUpVerifyOtp`.
 * - {@link useSignUpForm} — submit branches + `challengeId` / `otp` values.
 */
import React from "react"
import { RegistrationState } from "./RegistrationState"
import { OtpState } from "./OtpState"
import { useAppSelector } from "@/redux/hooks"
import { SignUpState } from "@/redux/slices/state"

/** Props for {@link SignUpSection}. */
export interface SignUpSectionProps {
    /** Hides `Modal.CloseTrigger` on both steps when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * Renders the active sign-up step from `signUpState`.
 */
export const SignUpSection = ({ hideCloseButton }: SignUpSectionProps = {}) => {
    const signUpState = useAppSelector((state) => state.state.signUpState)
    switch (signUpState) {
    case SignUpState.Registration:
        return <RegistrationState hideCloseButton={hideCloseButton} />
    case SignUpState.Otp:
        return <OtpState hideCloseButton={hideCloseButton} />
    default:
        return null
    }
}

import React from "react"
import type { FollowListTab } from "@/hooks/zustand/overlay/store"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Box } from "@/components/frames/Box"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"
import { InfiniteScrollSentinel } from "@/components/blocks/async/InfiniteScrollSentinel"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * `_FollowListModal` — the presentational half of {@link FollowListModal}
 * (`index.tsx`): the followers / following lists for one profile, each an
 * infinite-scroll roster of clickable users. Composes `ModalShell` + `Tabs`
 * (a count beside each label) + `SurfaceCardList` (free-form rows reusing the
 * `UserCell` composite) inside a bounded scroll region. Error/empty fall to
 * the shared `AsyncContentError`/`AsyncContentEmpty` frames, dropped into
 * `SurfaceCardList`'s own `errorState`/`emptyState` slots (`isEmpty` is
 * derived by that list from `items.length`, never passed in separately);
 * otherwise the tree renders with `isSkeleton` threaded into each
 * placeholder row's `UserCell`. See `tiers/split.md` — the connected
 * `index.tsx` (unchanged public name `FollowListModal`) owns the overlay
 * store, the two `useSWRInfinite` hooks (only the active tab fetches), and
 * every translated string.
 */

/** The two follow-graph directions, in tab order. */
const TABS: ReadonlyArray<FollowListTab> = ["followers", "following"]

/** How many placeholder rows mirror the list while the first page hasn't landed yet. */
const FOLLOW_LIST_SKELETON_ROW_COUNT = 5

/** One row of either list, already resolved by the connected `FollowListModal` — no raw entity. */
export interface FollowListRow {
    /** Opaque id — the row's `key`; also resolves the profile route on click. */
    globalId: string
    username: string
    /** Falls back to {@link FollowListRow.username} at the connected layer when unset. */
    displayName: string
    avatar?: string | null
    /** `@username`, already built by the connected layer. */
    handle: string
}

/** All display text, already localized by the connected `FollowListModal`; a story passes i18n keys. */
export interface FollowListModalLabels {
    title: string
    followersTab: string
    followingTab: string
    /** `t("followList.empty.<tab>")` for the CURRENTLY active tab, already picked. */
    empty: string
    errorTitle: string
    errorRetry: string
}

/** Props for {@link _FollowListModal} — presentational; all data resolved, no fetch/store/i18n. */
export interface FollowListModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /** Active direction (controlled — the connected half gates which `useSWRInfinite` hook fetches). */
    tab: FollowListTab
    onTabChange: (tab: FollowListTab) => void
    /** Follower / following counts, shown beside each tab's label. */
    counts: Record<FollowListTab, number>
    /** The active tab's rows (nearest page first), already resolved. Empty while {@link isSkeleton} is on. */
    rows: Array<FollowListRow>
    /** Go to a user's profile — the connected half also closes the modal in the same handler. */
    onOpenUser: (username: string) => void
    /** `true` -> the sentinel below the list can still grow it. */
    hasMore: boolean
    /** Grow the active list by one page. */
    onLoadMore: () => void
    /** A page is already in flight — the sentinel stays detached meanwhile. */
    isLoadingMore?: boolean
    /** First load of the active tab, nothing in hand yet -> the list mirrors itself. */
    isSkeleton?: boolean
    /** Truthy -> the list falls to its error message (beats the skeleton, per `SurfaceCardList`). */
    error?: unknown
    onRetry: () => void
    labels: FollowListModalLabels
}

/**
 * The follow-list modal. See the file header for the full contract.
 *
 * @param props - {@link FollowListModalProps}
 */
export const _FollowListModal = ({
    isOpen,
    onOpenChange,
    tab,
    onTabChange,
    counts,
    rows,
    onOpenUser,
    hasMore,
    onLoadMore,
    isLoadingMore = false,
    isSkeleton = false,
    error,
    onRetry,
    labels,
}: FollowListModalProps) => {
    const tabLabel: Record<FollowListTab, string> = {
        followers: labels.followersTab,
        following: labels.followingTab,
    }

    // A count beside a tab label is not `TabItem.badge` (that anchors a
    // notification-style chip OVER the label, `color="danger"` — the wrong
    // voice for a plain quantity). No block owns "label + muted count" either,
    // so this stays minimal, inline composition of existing atoms/frames.
    const tabItems: Array<TabItem> = TABS.map((tabId) => ({
        key: tabId,
        label: (
            <StackH
                gap={3}
                principle="value-row"
                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                align="center"
                items={[
                    () => <>{tabLabel[tabId]}</>,
                    () => <Typography size="sm" color="muted" tabularNums text={String(counts[tabId])} />,
                ]}
            />
        ),
    }))

    const skeletonRows: Array<SurfaceCardListItem> = Array.from(
        { length: FOLLOW_LIST_SKELETON_ROW_COUNT },
        (_row, index) => ({
            key: `skeleton-${index}`,
            content: () => <UserCell username="" handle="@" isSkeleton />,
        }),
    )

    const followRows: Array<SurfaceCardListItem> = rows.map((row) => ({
        key: row.globalId,
        content: () => (
            <UserCell
                username={row.username}
                displayName={row.displayName}
                avatar={row.avatar}
                handle={row.handle}
            />
        ),
        onPress: () => onOpenUser(row.username),
    }))

    const listBody: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={2}
            items={[
                () => (
                    <SurfaceCardList
                        items={isSkeleton ? skeletonRows : followRows}
                        isSkeleton={isSkeleton}
                        error={error}
                        errorState={() => (
                            <AsyncContentError
                                title={labels.errorTitle}
                                onRetry={onRetry}
                                retryLabel={labels.errorRetry}
                            />
                        )}
                        emptyState={() => <AsyncContentEmpty title={labels.empty} />}
                    />
                ),
                // grow the list as the sentinel scrolls into view — only while the
                // content branch is actually on screen (the error/skeleton/empty
                // branches above have nothing below them worth loading more of).
                ...(!isSkeleton && !error && rows.length > 0
                    ? [() => (
                        <InfiniteScrollSentinel
                            onReach={onLoadMore}
                            disabled={!hasMore || isLoadingMore}
                        />
                    )]
                    : []),
            ]}
        />
    )

    // Tabs <-> list-below = 2 different-function zones (nav vs content) -> gap-6,
    // not gap-3 (fe/foundations/gap.md's between-block rule).
    const modalBody: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={6}
            items={[
                () => (
                    <Tabs
                        items={tabItems}
                        selectedKey={tab}
                        onSelectionChange={(key) => onTabChange(key as FollowListTab)}
                        ariaLabel={labels.title}
                        variant="secondary"
                    />
                ),
                // NEW-VOCABULARY GAP: no frame owns "cap this region's height and
                // scroll it locally" outside a page shell — `ScrollArea`'s
                // `classNames` is a closed, positioning-only enum (no height
                // values), and `PinnedTrack` hard-owns the page-shell's own
                // `sticky top-0 z-40` for its one real consumer. `ScrollArea`
                // still owns the `overflow-y-auto` behaviour; only the height
                // cap itself has nowhere to live yet, so it goes through `Box`
                // (the sanctioned raw-appearance escape hatch) rather than a
                // bare `div`.
                () => (
                    <Box className="max-h-[60vh]">
                        <ScrollArea axis="y" body={listBody} />
                    </Box>
                ),
            ]}
        />
    )

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            size="sm"
            title={labels.title}
            body={modalBody}
            identity={{ tier: "overlay", component: "FollowListModal" }}
        />
    )
}

import React from "react"
import { CaretRightIcon, LockIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Chip } from "@/components/atoms/chips/Chip"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { GLOBAL_SEARCH_KIND_ICON, type GlobalSearchModalLabels, type GlobalSearchResultRow } from "../../component"

/** Props for {@link GlobalSearchContentBlock}. */
export interface GlobalSearchContentBlockProps {
    /** Rows of ONE bucket, in display order. */
    items: Array<GlobalSearchResultRow>
    /** The chip/hint labels this block renders. */
    labels: Pick<GlobalSearchModalLabels, "enrolled" | "free" | "viewCourse" | "premiumLock">
    /** Fired when a row is pressed. */
    onSelect: (row: GlobalSearchResultRow) => void
}

/**
 * Splits `<em>match</em>` out of a snippet line into an emphasized span,
 * trimming a fixed window of context around it. Plain text passes through
 * unchanged.
 */
const renderEmText = (text: string) => {
    const match = text.match(/<em>(.*?)<\/em>/)
    if (!match || match.index === undefined) {
        return text
    }

    const before = 10
    const after = 40
    const start = Math.max(0, match.index - before)
    const end = Math.min(text.length, match.index + match[0].length + after)
    const sliced = text.slice(start, end)
    const parts = sliced.split(/(<em>.*?<\/em>)/g)

    return (
        <>
            {start > 0 ? "…" : null}
            {parts.map((part, index) => {
                if (part.startsWith("<em>") && part.endsWith("</em>")) {
                    const content = part.replace(/<\/?em>/g, "")
                    return <Typography key={index} size="xs" color="accent-soft" weight="semibold" isInline text={content} />
                }
                return <span key={index}>{part}</span>
            })}
            {end < text.length ? "…" : null}
        </>
    )
}

/** One row's free-form body: kind icon + title + state badges, then any matched snippet lines. */
const resultRowContent = (row: GlobalSearchResultRow, labels: GlobalSearchContentBlockProps["labels"]) => {
    const Icon = GLOBAL_SEARCH_KIND_ICON[row.kind]
    const titleRow = [
        () => (
            <Typography
                size="sm"
                prefixIcon={Icon}
                truncate
                classNames={["flex-1", "min-w-0"]}
                text={row.title}
            />
        ),
        ...(row.showEnrolledChip ? [() => <Chip tone="success" text={labels.enrolled} />] : []),
        ...(row.showFreeChip ? [() => <Chip tone="success" text={labels.free} />] : []),
        ...(row.showPremiumLock ? [() => (
            <LockIcon aria-label={labels.premiumLock} focusable="false" className="size-4 shrink-0 text-muted" />
        )] : []),
        ...(row.showViewCourseHint ? [() => (
            <Typography
                size="xs"
                color="accent-soft"
                suffixIcon={CaretRightIcon}
                text={labels.viewCourse}
            />
        )] : []),
    ]
    const rowItems = [
        () => (
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                items={titleRow}
            />
        ),
        ...(row.textLines.length > 0 ? row.textLines.map((line) => () => (
            <Typography size="xs" color="muted" text={renderEmText(line)} />
        )) : []),
    ]
    return <StackV gap={2} items={rowItems} />
}

/**
 * The row list of one global-search group. Each row is a FREE-FORM
 * `SurfaceCardList` item — kind icon, title, state badges (enrolled / free /
 * premium-lock / "view course"), then any matched snippet lines. The whole
 * row is one press target, navigating via the connected half's
 * {@link GlobalSearchContentBlockProps.onSelect}.
 *
 * @param props - {@link GlobalSearchContentBlockProps}
 */
export const GlobalSearchContentBlock = ({ items, labels, onSelect }: GlobalSearchContentBlockProps) => {
    if (items.length === 0) {
        return null
    }

    const listItems: Array<SurfaceCardListItem> = items.map((row) => ({
        key: row.id,
        content: () => resultRowContent(row, labels),
        onPress: () => onSelect(row),
    }))

    return <SurfaceCardList items={listItems} />
}

/** Folder-matching alias (export-matches-folder) — keep `GlobalSearchContentBlock` as the public name. */
export { GlobalSearchContentBlock as Block }

import React from "react"
import { FlameIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import type { GlobalSearchModalLabels, GlobalSearchModalPopularCourse } from "../../component"

/** Props for {@link GlobalSearchEmpty}. */
export interface GlobalSearchEmptyProps {
    /** `true` when a non-blank query is active but matched nothing. */
    hasQuery: boolean
    /** Popular-course fallback rows — already the viewer's recommendations, priced. */
    popularCourses: Array<GlobalSearchModalPopularCourse>
    /** Every translated string this modal renders. */
    labels: Pick<GlobalSearchModalLabels, "noResults" | "idleHint" | "popular">
    /** Fired when a popular-course row is pressed. */
    onSelectCourse: (course: GlobalSearchModalPopularCourse) => void
}

/**
 * Empty state for the global search palette.
 *
 * - Query typed, no hits → a "no matches" message.
 * - Idle (blank query) → popular courses as quick links, so the palette is
 *   never a dead blank.
 *
 * @param props - {@link GlobalSearchEmptyProps}
 */
export const GlobalSearchEmpty = ({ hasQuery, popularCourses, labels, onSelectCourse }: GlobalSearchEmptyProps) => {
    // No popular courses to fall back on → just the appropriate hint line (never a blank).
    if (popularCourses.length === 0) {
        return <AsyncContentEmpty title={hasQuery ? labels.noResults : labels.idleHint} />
    }

    const items: Array<SurfaceCardListItem> = popularCourses.map((course) => ({
        key: course.id,
        leadingIcon: FlameIcon,
        title: course.title,
        meta: () => <PriceTagInline discounted={course.discountedPriceVnd} />,
        onPress: () => onSelectCourse(course),
    }))

    // A query WAS typed but matched nothing → keep the "not found" line, then fall
    // through to the popular list below it, so the palette is never a dead end.
    return (
        <StackV
            gap={3}
            items={[
                ...(hasQuery ? [() => <Typography size="sm" color="muted" text={labels.noResults} />] : []),
                () => <SurfaceCardList label={labels.popular} subtleLabel items={items} />,
            ]}
        />
    )
}

